# ---------------------------------------------------------------- modules
def mod(id, kind, code, titre, jour, duree, comp, presentation, slides, logistique='Salle de formation, vidéoprojecteur ou tableau blanc ou paper board',
        profil='FPS', docs_f='Classeurs SUAP', docs_a='Classeurs SUAP', evaluation='Information sur le niveau du groupe.', valide=False, msp=None):
    return {'id': id, 'kind': kind, 'code': code, 'titre': titre, 'jour': jour, 'duree': duree, 'competences': comp,
            'logistique': logistique, 'profil': profil, 'presentation': presentation, 'docsFormateurs': docs_f,
            'docsApprenants': docs_a, 'evaluation': evaluation, 'slides': slides, 'valide': valide, 'msp': msp or []}

def S(titre, *pts, note=''):
    return {'titre': titre, 'points': list(pts), 'note': note}

